MAP
    NAME "SS_MAP_MCIR_VALVSUBSECTOR"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            'ows_title' 'Valvulas subsectores'
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_valvulas_subsector.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_MCIR_VALV_SUBSECTOR"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        METADATA
            'ows_title' 'Valvulas subsectores'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
            'ows_enable_request'  '*'
        END
        CONNECTIONTYPE POSTGIS
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'  
        DATA "geometry from (select  geometry, gid, numval, tipo from valvsubsectores) as c using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        TYPE POINT
        MINSCALE 1
        LABELITEM "numval"
        MAXSCALE 150000
        CLASSITEM "tipo"
        CLASS
            NAME "tapa ciega"
            EXPRESSION ([tipo]= 2)
            STYLE
                SYMBOL "aguaA"
                SIZE 10
                COLOR 32 207 34
                OUTLINECOLOR -1 -1 -1
            END #STYLE
            LABEL
                TYPE TRUETYPE
                SIZE 19
                COLOR 0 0 0   
                PARTIALS FALSE      
                FONT ARIAL
            END #LABEL
        END #CLASS
        CLASS
            NAME "reduccion"
            EXPRESSION  ([tipo]= 3)
            STYLE
                SYMBOL "aguaB"
                SIZE 10
                COLOR 32 207 34
                OUTLINECOLOR -1 -1 -1
            END #STYLE
            END #CLASS
            CLASS
            NAME "medidor"
            EXPRESSION ([tipo]= 4)
            STYLE
                SYMBOL "aguaC"
                SIZE 10
                COLOR 32 207 34
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
        CLASS
            NAME "bomba"
            EXPRESSION ([tipo]= 5)
            STYLE
                SYMBOL "aguaJ"
                SIZE 10
                COLOR 32 207 34
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
        CLASS
            NAME "no definido"
            EXPRESSION ([tipo]= 20)
            STYLE
                SYMBOL "X"
                SIZE 10
                COLOR 32 207 34
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME 'SS_MAP_MCIR_COMPUERTA_CERRADA'
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from (select gid, geometry from valvsubsectores WHERE tipo = 1 and descripcio = 1 and cerrada = 'S') as tmp using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        STATUS DEFAULT
        TYPE POINT
        MINSCALE 1
        MAXSCALE 15000
        CLASS
            NAME "Compuerta Cerrada"
            STYLE
                SYMBOL 'aguaD'
                SIZE 15
                COLOR 255 0 0
                OUTLINECOLOR -1 -1 -1
            END #STYLE
        END #CLASS
    END #LAYER
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_MCIR_MARIPOSA_CERRADA_01"
